"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export interface Avatar {
  initials: string;
  color: string;
  name: string;
  role: string;
}

export function AvatarGroup({
  people,
  maxVisible = 4,
}: {
  people: Avatar[];
  maxVisible?: number;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [hovered, setHovered] = useState<number | "overflow" | null>(null);
  const visiblePeople = people.slice(0, maxVisible);
  const hiddenPeople = people.slice(maxVisible);

  return (
    <div className="group flex items-center">
      {visiblePeople.map((person, i) => (
        <motion.div
          key={person.initials}
          whileHover={shouldReduceMotion ? undefined : { y: -4, zIndex: 10 }}
          className="relative"
          style={{ marginLeft: i === 0 ? 0 : -10, zIndex: visiblePeople.length - i }}
        >
          <motion.div
            onMouseEnter={() => setHovered(i)}
            onMouseLeave={() => setHovered(null)}
            onFocus={() => setHovered(i)}
            onBlur={() => setHovered(null)}
            tabIndex={0}
            whileHover={
              shouldReduceMotion ? undefined : { scale: 1.08, x: (i - (visiblePeople.length - 1) / 2) * 6 }
            }
            transition={{ type: "spring", stiffness: 400, damping: 22 }}
            className={`flex h-10 w-10 items-center justify-center rounded-full border-2 border-white text-xs font-semibold text-white shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 dark:border-slate-900 ${person.color}`}
          >
            {person.initials}
          </motion.div>
          <AnimatePresence>
            {hovered === i && (
              <div className="pointer-events-none absolute -top-2 left-1/2 z-20 -translate-x-1/2 -translate-y-full">
                <motion.div
                  role="tooltip"
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  transition={{ type: "spring", stiffness: 500, damping: 28 }}
                  style={{ transformOrigin: "bottom center" }}
                  className="whitespace-nowrap rounded-lg bg-slate-900 px-3 py-1.5 text-center shadow-lg dark:bg-slate-100"
                >
                  <p className="text-xs font-semibold text-white dark:text-slate-900">{person.name}</p>
                  <p className="text-[11px] text-slate-300 dark:text-slate-500">{person.role}</p>
                </motion.div>
                <span
                  aria-hidden
                  className="absolute left-1/2 top-full h-2 w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 bg-slate-900 dark:bg-slate-100"
                />
              </div>
            )}
          </AnimatePresence>
        </motion.div>
      ))}
      {hiddenPeople.length > 0 && (
        <motion.div
          onMouseEnter={() => setHovered("overflow")}
          onMouseLeave={() => setHovered(null)}
          onFocus={() => setHovered("overflow")}
          onBlur={() => setHovered(null)}
          tabIndex={0}
          whileHover={shouldReduceMotion ? undefined : { scale: 1.08 }}
          transition={{ type: "spring", stiffness: 400, damping: 22 }}
          style={{ marginLeft: -10 }}
          className="relative flex h-10 w-10 items-center justify-center rounded-full border-2 border-white bg-slate-100 text-xs font-semibold text-slate-600 shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 dark:border-slate-900 dark:bg-neutral-900 dark:text-slate-300"
        >
          +{hiddenPeople.length}
          <AnimatePresence>
            {hovered === "overflow" && (
              <div className="pointer-events-none absolute -top-2 left-1/2 z-20 -translate-x-1/2 -translate-y-full">
                <motion.div
                  role="tooltip"
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  transition={{ type: "spring", stiffness: 500, damping: 28 }}
                  style={{ transformOrigin: "bottom center" }}
                  className="space-y-1.5 rounded-lg bg-slate-900 px-3 py-2 text-left shadow-lg dark:bg-slate-100"
                >
                  {hiddenPeople.map((person) => (
                    <div key={person.initials} className="flex items-center gap-2">
                      <span
                        className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[9px] font-semibold text-white ${person.color}`}
                      >
                        {person.initials}
                      </span>
                      <span className="whitespace-nowrap text-xs font-medium text-white dark:text-slate-900">
                        {person.name}
                      </span>
                    </div>
                  ))}
                </motion.div>
                <span
                  aria-hidden
                  className="absolute left-1/2 top-full h-2 w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 bg-slate-900 dark:bg-slate-100"
                />
              </div>
            )}
          </AnimatePresence>
        </motion.div>
      )}
    </div>
  );
}
